Variasi List Linier
List Linier dengan Dummy 
Element
IF2110/IF2111 –Algoritma dan Struktur Data
Sekolah Teknik Elektro dan Informatika
Institut Teknologi BandungBahasan
Buatlah ADT list + driver dengan elemen dummy di akhir :
•Penunjuk first dan last (last element menunjuk keelemen dummy)
•Alamat dummy: tetap
•Representasi fisik: berkait dengan pointer
IF2110/Variasi List Linier 2
Representasi Fisik dengan Pointer
#define NILNULL
#define IDX_UNDEF -1
typedef intElType;
typedef structnode* Address;
typedef structnode { ElTypeinfo; Address next; } Node;
/* Definisi list: */
/* List kosong: First(L) = Last(L) = dummy@ */
/* Setiapelemendenganaddress P dapatdiacuInfo(P), Next(P) */
/* Elemendummy terletak pada last */
typedef struct{ 
address first;
address last;
} List;
/* Selektor */
#define INFO(P)  (P)->info
#define NEXT(P)  (P)->next
#define FIRST(L) ((L).first)
#define LAST(L)  ((L). last)
IF2110/Variasi List Linier 3Beberapa primitif
Buatlah sebagai latihan :
/* PROTOTYPE */
/****************** TEST LIST KOSONG ******************/
boolean isEmpty(List l);
/* Mengirim true jikalist kosong: FIRST(l) = dummy@ 
dan LAST(L) = dummy@ */
/****************** PEMBUATAN LIST KOSONG ******************/
voidCreateList (List *l);
/* I.S. sembarang */
/* F.S. Terbentuk list l kosong, dengansatuelemendummy */
/*      Jika gagalmakaFIRST(l) = LAST(l) = NIL dan list gagalterbentuk */
/****************** SEARCHING ******************/
intindexOf(List l, ElTypex);
/* Mengembalikan indeksnode list dengannilaiX, atauIDX_UNDEF jikatidakada*/
IF2110/Variasi List Linier 4Beberapa primitif
Buatlah sebagai latihan :
voidinsertFirst (List *l, ElTypex);
/* I.S. List l terdefinisi */
/* F.S. Menambahkan elemenx sebagai elemenpertama List l */
voidinsertLast (List *l, ElTypex);
/* I.S. List l terdefinisi */
/* F.S. x ditambahkan sebagai elementerakhir l yang baru, */
/*      yaitumenjadi elemensebelum elemendummy */
voiddeleteFirst (List *l, ElType*x);
/* I.S. List l tidakkosong*/
/* F.S. x adalahnilaielemenpertama list l sebelum penghapusan */
/*      Elemenlist berkurang satu(mungkin menjadi kosong) */
/*      First element ygbaruadalahsuksesor elemenpertama yang lama */
voiddeleteLast (List *l, ElType*x);
/* I.S. List l tidakkosong*/
/* F.S. x adalahterakhir sebelum dummy pada list sebelum penghapusan */
/*      Elemenlist berkurang satu(mungkin menjadi kosong) */
IF2110/Variasi List Linier 5Beberapa primitif
boolean isEmpty(List l) {
/* Mengirim true jikalist kosong*/
/* KamusLokal*/
/* Algoritma */
return(FIRST(l) == LAST(l));
}
IF2110/Variasi List Linier 6
Beberapa primitif
voidCreateList (List *l) {
/* I.S. Sembarang */
/* F.S. Terbentuk list l kosong, dengansatuelemendummy, 
jikaalokasi dummy berhasil */
/*      Jika gagalmakaFIRST(l) = LAST(l) = NIL dan list gagalterbentuk */
/* KamusLokal*/
address pDummy;
/* Algoritma */
pDummy= alokasi(0); /* INFO( pDummy) tidakdidefinisikan */
if(Pdummy!= Nil) {
FIRST(*L) = pDummy;
LAST(*L) = pDummy;
} else/* List gagalterbentuk */{
FIRST(*L) = NIL;
LAST(*L) = NIL;
}
}
IF2110/Variasi List Linier 7
Beberapa primitif
intindexOf(List l, ElTypex) {
/* Mengembalikan indeksnode list dengannilaiX, atauIDX_UNDEF jikatidakada*/
/* KamusLokal*/
address p;
intidx;
/* Algoritma */
INFO(LAST(l)) = x; /* letakkan X di sentinel */
p = FIRST(l);
idx= 0;
while(INFO(p) != x) {
p = NEXT(p);
idx++;
} /* INFO(p) = x */
if(p != LAST(l)) { /* bukanketemudi sentinel */
returnidx;
} else/* p = LAST(l), ketemudi sentinel */ {
returnIDX_UNDEF;
}
}
IF2110/Variasi List Linier 8
Beberapa primitif
voidinsertFirst (List *l, ElTypex) {
/* I.S. List l terdefinisi */
/* F.S. Menambahkan elemenx sebagai elemenpertama List l */
/* KamusLokal*/
address p;
/* Algoritma */
p = newNode(x);
if (p != NIL) {
NEXT(p) = FIRST(*l);
FIRST(*l) = p;
}
}
IF2110/Variasi List Linier 9
Beberapa primitif
voidinsertLast (List *l, ElTypex) {
/* I.S. List l terdefinisi */
/* F.S. x ditambahkan sebagai elementerakhir l yang baru*/
/* Alamat elemendummy tidakberubah */
/* KamusLokal*/
address p, last;
/* Algoritma */
if(isEmpty(*l)) {
insertFirst (l,x);
} else{
p = newNode(x);
if (p != NIL) {
last = FIRST(*l);
while(NEXT(last) != LAST(*l)) {
last = NEXT(last);
} /* NEXT(last) == LAST(*l) alias dummy */
NEXT(last) = p;
NEXT(p) = LAST(*l);
}
}
} IF2110/Variasi List Linier 10
Beberapa primitif
voidinsertLast (List *l, ElTypex) {
/* I.S. List l terdefinisi */
/* F.S. x ditambahkan sebagai elementerakhir l yang baru*/
/* Versijikaalamatelemendummy bolehberubah */
/* KamusLokal*/
/* Algoritma */
if(isEmpty(*l)) {
insertFirst (l,x);
} else{
INFO(LAST(*l)) = x;
p = newNode(x); /* dummy baru*/
if (p != NIL) {
NEXT(LAST(*l)) = p;
LAST(*l) = p;
}
}
}
IF2110/Variasi List Linier 11
Beberapa primitif
voiddeleteFirst (List *l, ElType*x) {
/* I.S. List l tidakkosong*/
/* F.S. x adalahelemenpertama list l sebelum penghapusan */
/*      Elemenlist berkurang satu(mungkin menjadi kosong) */
/*      First element ygbaruadalahsuksesor elemenpertama yang lama */
/* KamusLokal*/
address p;
/* Algoritma */
p = FIRST(*l);
*x = INFO(p);
FIRST(*l) = NEXT(FIRST(*l));
free(p);
}
IF2110/Variasi List Linier 12
Beberapa primitif
voiddeleteLast (List *l, ElType*x) {
/* I.S. List l tidakkosong*/
/* F.S. x adalahelementerakhir list l sebelum penghapusan */
/*      Elemenlist berkurang satu(mungkin menjadi kosong) */
/*      Last element baruadalahpredesesor elementerakhir yglama, jikaada*/
/* KamusLokal*/
address last, precLast ;
/* Algoritma */
last = FIRST(*l); precLast = NIL;
while(NEXT(last) != LAST(*l)) {
precLast = last; last = NEXT(last);
}
*x = INFO (last);
if(precLast == NIL) { /* kasussatuelemen*/
FIRST(*l) = LAST(*l); 
} else{ 
NEXT(precLast ) = LAST(*l); 
}
free(last);
}
