/* File: prioqueuelist .h*/
#ifndef_PRIOQUEUELIST _H
#define_PRIOQUEUELIST _H
#include "boolean.h "
#include <stdlib.h >
#define NilNULL
/* Deklarasi type elemen */
typedef intElType;
/* Priority Queue denganrepresentasi berkait denganpointer */
typedef structtNode *address ;
typedef structtNode { 
ElType info;
int prio;
address next ; 
} Node; 
/* Type PrioQueue dengan HEAD */
typedef struct{
address addrHead; /* alamatelemen pertama */
} PrioQueue ;
