#include "mesinkata1.h"
boolean endKata;
Kata currentKata ;
voidignoreBlank () {
/* Mengabaikan satuataubeberapa BLANK
I.S.: cc sembarang
F.S.: cc ≠ BLANK */
/* KamusLokal*/
/* Algoritma */
while(cc == BLANK) {
adv();
} /* cc != BLANK */
}
IF2110/IF2111 Mesin Karakter dan Mesin Kata 4mesinkata1.c (model akuisisi v.1)
voidstartKata () {
/* I.S.: cc sembarang
F.S.: endKata = true, dan cc = MARK; 
atauendKata = false, currentKata adalahkata yang sudah
diakuisisi ,
cc karakter pertama sesudah karakter terakhir kata */
/* KamusLokal*/
/* Algoritma */
start();
ignoreBlank ();
if(cc == MARK) {
endKata = true;
} else/* cc != MARK */ {
endKata = false;
salinKata ();
}
}
IF2110/IF2111 Mesin Karakter dan Mesin Kata 5mesinkata1.c (model akuisisi v.1)
voidadvKata() {
/* I.S.: cc adalahkarakter pertama kata yang akandiakuisisi
F.S.: currentKata adalahkata terakhir yang sudahdiakuisisi , 
cc adalahkarakter pertama darikata berikutnya , 
mungkin MARK 
Proses: Akuisisi kata menggunakan procedure salinKata */
/* KamusLokal*/
/* Algoritma */
ignoreBlank ();
if(cc == MARK) {
endKata = true;
} else/* cc != MARK */ {
salinKata ();
}
}
IF2110/IF2111 Mesin Karakter dan Mesin Kata 6mesinkata1.c (model akuisisi v.1)
voidsalinKata () {
/* Mengakuisisi kata, menyimpan dalamcurrentKata
I.S.: cc adalahkarakter pertama darikata
F.S.: currentKata berisikata yang sudahdiakuisisi ; 
cc = BLANK ataucc = MARK; 
cc adalahkarakter sesudah karakter terakhir yang 
diakuisisi */
/* KamusLokal*/
inti; /* definisi */
/* Algoritma*/
i= 0;/* inisialisasi */
while((cc != MARK) && (cc != BLANK)) {
currentKata .buffer[i] = cc;
adv();
i++;
} /* cc = MARK or cc = BLANK */
currentKata .length= i;
}
