IF2110/IF2111 Stack dengan Struktur Berkait 10
 STEI -ITBADT Stack Representasi List
voidpop(Stack * s, ElType*x);
/* Menghapus Top dariStack s */
/* I.S. s tidakmungkin kosong*/
/* F.S. x adalahnilaielemenTop yang lama, */
/*      elemenTop yang lama didealokasi */
/* Pada dasarnya adalahoperasi deleteFirst pada list linier */
/* KamusLokal*/
address p;
/* Algoritma */
*x = TOP(*s);
p = ADDR_TOP (*s);
ADDR_TOP (*s) = NEXT(ADDR_TOP (*s));
NEXT(p) = NIL;
free(p);
}
