/* File: queue.h */
#ifndefQUEUE_H
#define QUEUE_H
#include "boolean.h "
#include <stdlib.h >
#define IDX_UNDEF -1
/* Definisi elemendan address */
typedef intElType;
/* Contohstruktur type Queue: array statik, indekshead dan indekstail disimpan */
typedef struct{
ElTypebuffer[CAPACITY ]; 
intidxHead;
intidxTail;
} Queue;
/* Definisi Queue kosong: idxHead = idxTail = IDX_UNDEF. */
23/09/2021 IF2110/Queue 2NOTE: if you want flexibility, buffer should be an ElType *
and you will need malloc() in CreateQueue . You will also
have to have a destructor, e.g., DestroyQueue (),
where you call free(buffer).ADT Queue dengan C –alt-2 (alokasi memori statik )
/********** AKSES ( Selektor ) **********/
#define IDX_HEAD( q) (q).idxHead
#define IDX_TAIL( q) (q).idxTail
#define HEAD(q) (q).buffer[(q).idxHead]
#define TAIL(q) (q).buffer[(q).idxTail]
/********** Konstruktor **********/
voidCreateQueue (Queue *q);
/* I.S. Sembarang
F.S. Membuat sebuahQueue q yang kosongberkapasitas CAPACITY
jadiindeksnya antara0..CAPACITY -1
CiriQueue kosong: idxHead dan idxTail bernilai IDX_UNDEF */
