/*** Primitif Add/Delete ***/
voidenqueue (Queue *q, ElTypeval);
/* Proses: Menambahkan valsebagai elemenQueue q.
I.S. queue mungkin kosong, TIDAK penuh*/
F.S. queue bertambah elemenvalsebagai tail yang baru, TAIL bergeser ke kanan */
Jika IDX_TAIL(queue)=CAPACITY -1, makageserisitabel, shgIDX_HEAD(queue)=0 */
voiddequeue(Queue *q, ElType* val);
/* Menghapus head dariQueue q.
I.S. queue tidakkosong
F.S. valberisinilaihead yang lama. 
Jika queue tidakmenjadi kosong,
queue.idxHead berpindah keelemenberikutnya pada queue.
Jika queue menjadi kosong,
queue.idxHead dan queue.idxTail menjadi bernilai IDX_UNDEF. */
#endif
23/09/2021 IF2110/Queue 5ADT Queue dengan C –alt-2
voidCreateQueue (Queue *q) { 
/* I.S. ... F.S. ... */
/* KAMUS LOKAL */
/* ALGORITMA */
IDX_HEAD (*q) = IDX_UNDEF ;
IDX_TAIL (*q) = IDX_UNDEF ;
}
boolean isEmpty(Queue q) { 
/* Mengirim ... */
/* KAMUS LOKAL */
/* ALGORITMA */
return(IDX_HEAD (q) == IDX_UNDEF ) && (IDX_TAIL (q) == IDX_UNDEF );
}
23/09/2021 IF2110/Queue 6ADT Queue dengan C –alt-2
boolean isFull(Queue q) { 
/* Mengirim ... */
/* KAMUS LOKAL */
/* ALGORITMA */
return(IDX_HEAD (q) == 0) && (IDX_TAIL (q) == CAPACITY -1);
