voidenqueue(Queue * q, ElTypex) {
/* Proses: Mengalokasi x dan menambahkan x pada bagianTail dariq
jikaalokasi berhasil ; jikaalokasi gagalq tetap*/
/*         Pada dasarnya adalahproses insertLast */
/* I.S. q mungkin kosong*/
/* F.S. x menjadi Tail, Tail " maju" */
/* KamusLokal*/
address p;
/* Algoritma */
p = newNode(x);
if(p != NIL) {
if(isEmpty(*q)) {
ADDR_HEAD (*q) = p; 
} else{
NEXT(ADDR_TAIL (*q)) = p;
}
ADDR_TAIL (*q) = p; 
} /* else: alokasi gagal, q tetap*/
}
