voiddequeue(Queue * q, ElType*x) {
/* Proses: Menghapus x pada bagianHEAD dariq dan mendealokasi
elemenHEAD */
/*         Pada dasarnya operasi delete first */
/* I.S. q tidakmungkin kosong*/
/* F.S. x = nilaielemenHEAD pd I.S., HEAD " mundur" */
/* KamusLokal*/
address p;
/* Algoritma */
*x = HEAD(*q);
p = ADDR_HEAD (*q);
ADDR_HEAD (*q) = NEXT(ADDR_HEAD (*q));
if(ADDR_HEAD (*q)==NIL) {
ADDR_HEAD (*q) = NIL;
}
NEXT(p) = NIL;
free(p);
}
