#define INFO(p) (p) ->info
#define NEXT(p) (p) ->next
Address newNode(ElTypeval);
#endif/* node.c*/
#include "node.h"
#include <stdlib.h >
Address newNode(ElTypeval) {
Address p = (Address)
malloc(sizeof(Node));
if(p!=NULL) {
INFO(p) = val;
NEXT(p) = NULL;
}
returnp;
}
